import React, { useCallback, useContext, useEffect, useState } from 'react';
import { useSelector } from 'react-redux';
import { useNavigate, useLocation } from 'react-router-dom';
import { providerErrors, serializeError } from '@metamask/rpc-errors';
import { getTokenTrackerLink } from '@metamask/etherscan-link';
import classnames from 'clsx';
import {
  Box,
  BoxAlignItems,
  BoxFlexDirection,
  BoxFlexWrap,
  BoxJustifyContent,
} from '@metamask/design-system-react';
import { PageContainerFooter } from '../../components/ui/page-container';
import { I18nContext } from '../../contexts/i18n';
import { useAnalytics } from '../../hooks/useAnalytics';
import { getMostRecentOverviewPage } from '../../ducks/history/history';
import {
  resolvePendingApproval,
  rejectPendingApproval,
} from '../../store/actions';
import {
  MetaMetricsEventCategory,
  MetaMetricsEventName,
  MetaMetricsTokenEventSource,
} from '../../../shared/constants/metametrics';
import { AssetType } from '../../../shared/constants/transaction';
import {
  BUTTON_SIZES,
  ButtonIcon,
  ButtonIconSize,
  ButtonLink,
  IconName,
  Text,
} from '../../components/component-library';
import { getCurrentChainId } from '../../../shared/lib/selectors/networks';
import {
  getRpcPrefsForCurrentProvider,
  getSuggestedNfts,
  getIpfsGateway,
  getNetworkIdentifier,
  getSelectedAccountCachedBalance,
  getAddressBookEntryOrAccountName,
} from '../../selectors';
import { getSelectedInternalAccount } from '../../../shared/lib/selectors/accounts';
import NftDefaultImage from '../../components/app/assets/nfts/nft-default-image/nft-default-image';
import { getAssetImageURL, shortenAddress } from '../../helpers/utils/util';
import {
  IconColor,
  TextAlign,
  TextVariant,
  TextColor,
} from '../../helpers/constants/design-system';
import NetworkAccountBalanceHeader from '../../components/app/network-account-balance-header/network-account-balance-header';
import { NETWORK_TO_NAME_MAP } from '../../../shared/constants/network';
import SiteOrigin from '../../components/ui/site-origin/site-origin';
import { PRIMARY } from '../../helpers/constants/common';
import { useUserPreferencedCurrency } from '../../hooks/useUserPreferencedCurrency';
import { useCurrencyDisplay } from '../../hooks/useCurrencyDisplay';
import { useOriginMetadata } from '../../hooks/useOriginMetadata';
import { isEqualCaseInsensitive } from '../../../shared/lib/string-utils';
// eslint-disable-next-line import-x/no-restricted-paths -- TODO(ADR-0021): route-isolation backlog
import { Nav } from '../confirmations/components/confirm/nav';
import { hideAppHeader } from '../routes/utils';
import { useDispatch } from '../../store/hooks';

const ConfirmAddSuggestedNFT = () => {
  const t = useContext(I18nContext);
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const location = useLocation();

  const hasAppHeader = location?.pathname ? !hideAppHeader({ location }) : true;

  const classNames = classnames(
    'confirm-add-suggested-nft page-container h-full',
    {
      'confirm-add-suggested-nft--has-app-header-multichain': hasAppHeader,
    },
  );

  const mostRecentOverviewPage = useSelector(getMostRecentOverviewPage);
  const suggestedNftsNotSorted = useSelector(getSuggestedNfts);
  const suggestedNfts = suggestedNftsNotSorted.sort(
    (a, b) => a.requestData.asset.tokenId - b.requestData.asset.tokenId,
  );
  const rpcPrefs = useSelector(getRpcPrefsForCurrentProvider);
  const chainId = useSelector(getCurrentChainId);
  const ipfsGateway = useSelector(getIpfsGateway);
  const { trackEvent, createEventBuilder } = useAnalytics();
  const networkIdentifier = useSelector(getNetworkIdentifier);
  const { address: selectedAddress } = useSelector(getSelectedInternalAccount);
  const selectedAccountBalance = useSelector(getSelectedAccountCachedBalance);
  const accountName = useSelector((state) =>
    getAddressBookEntryOrAccountName(state, selectedAddress),
  );
  const [suggestedNftsWithImages, setSuggestedNftsWithImages] = useState([]);

  const networkName = NETWORK_TO_NAME_MAP[chainId] || networkIdentifier;

  const {
    currency: primaryCurrency,
    numberOfDecimals: primaryNumberOfDecimals,
  } = useUserPreferencedCurrency(PRIMARY, { ethNumberOfDecimals: 4 });

  const [primaryCurrencyValue] = useCurrencyDisplay(selectedAccountBalance, {
    numberOfDecimals: primaryNumberOfDecimals,
    currency: primaryCurrency,
  });

  const originMetadata = useOriginMetadata(suggestedNfts[0]?.origin) || {};
  const approvalId = suggestedNfts[0]?.id;

  const handleAddNftsClick = useCallback(async () => {
    await Promise.all(
      suggestedNfts.map(async ({ requestData: { asset }, id }) => {
        await dispatch(resolvePendingApproval(id, null));

        trackEvent(
          createEventBuilder(MetaMetricsEventName.NftAdded)
            .addCategory(MetaMetricsEventCategory.Wallet)
            .addSensitiveProperties({
              token_contract_address: asset.address,
              token_symbol: asset.symbol,
              token_id: asset.tokenId,
              token_standard: asset.standard,
              asset_type: AssetType.NFT,
              source: MetaMetricsTokenEventSource.Dapp,
            })
            .build(),
        );
      }),
    );
    navigate(mostRecentOverviewPage);
  }, [
    createEventBuilder,
    dispatch,
    navigate,
    trackEvent,
    mostRecentOverviewPage,
    suggestedNfts,
  ]);

  const handleCancelNftClick = useCallback(async () => {
    await Promise.all(
      suggestedNfts.map(async ({ id }) => {
        return dispatch(
          rejectPendingApproval(
            id,
            serializeError(providerErrors.userRejectedRequest()),
          ),
        );
      }),
    );
    navigate(mostRecentOverviewPage);
  }, [dispatch, navigate, mostRecentOverviewPage, suggestedNfts]);

  useEffect(() => {
    const goBackIfNoSuggestedNftsOnFirstRender = () => {
      if (!suggestedNfts.length) {
        navigate(mostRecentOverviewPage);
      }
    };
    goBackIfNoSuggestedNftsOnFirstRender();
  }, [navigate, mostRecentOverviewPage, suggestedNfts]);

  let origin;
  let link;
  if (suggestedNfts.length) {
    try {
      const url = new URL(suggestedNfts[0].origin);
      origin = url.host;
      link = url.href;
    } catch {
      origin = 'dapp';
    }
  }

  useEffect(() => {
    const addImageUrlToSuggestedNFTs = async () => {
      const suggestedNftWithImages = await Promise.all(
        suggestedNfts.map(async (item) => {
          const imgUrl = await getAssetImageURL(
            item.requestData.asset.image,
            ipfsGateway,
          );
          return {
            ...item,
            requestData: {
              ...item.requestData,
              asset: {
                ...item.requestData.asset,
                assetImageUrl: imgUrl,
              },
            },
          };
        }),
      );
      setSuggestedNftsWithImages(suggestedNftWithImages);
    };

    addImageUrlToSuggestedNFTs();
  }, [suggestedNfts, ipfsGateway]); // rerender when suggestedNfts or ipfsGateway changes

  return (
    <Box
      className={`flex h-full w-full ${classNames}`}
      flexDirection={BoxFlexDirection.Column}
    >
      <Nav confirmationId={approvalId} />
      <Box paddingBottom={2} className="confirm-add-suggested-nft__header">
        <NetworkAccountBalanceHeader
          accountName={accountName}
          accountBalance={primaryCurrencyValue}
          accountAddress={selectedAddress}
          networkName={networkName}
          chainId={chainId}
        />
        <Box
          className="flex"
          paddingTop={4}
          paddingRight={4}
          paddingLeft={4}
          justifyContent={BoxJustifyContent.Center}
        >
          <SiteOrigin
            chip
            siteOrigin={originMetadata.origin}
            title={originMetadata.origin}
            iconSrc={originMetadata.iconUrl}
            iconName={originMetadata.hostname}
          />
        </Box>
        <Text
          variant={TextVariant.headingLg}
          textAlign={TextAlign.Center}
          margin={2}
        >
          {t('addSuggestedNFTs')}
        </Text>
        <Text variant={TextVariant.bodyMd} textAlign={TextAlign.Center}>
          {t('wantsToAddThisAsset', [
            origin === 'dapp' ? (
              <Text key={origin} variant={TextVariant.bodyMd} fontWeight="bold">
                {origin}
              </Text>
            ) : (
              <ButtonLink
                key={origin}
                size={BUTTON_SIZES.INHERIT}
                href={link}
                target="_blank"
              >
                {origin}
              </ButtonLink>
            ),
          ])}
        </Text>
      </Box>
      <Box className="page-container__content confirm-add-suggested-nft__content">
        <Box className="rounded-md confirm-add-suggested-nft__card" padding={2}>
          <Box
            className={classnames({
              'confirm-add-suggested-nft__nft-list': suggestedNfts.length > 1,
            })}
          >
            {suggestedNfts.map(
              ({
                id,
                requestData: {
                  asset: { address, tokenId, symbol, name },
                },
              }) => {
                const found = suggestedNftsWithImages.find(
                  (elm) =>
                    elm.requestData.asset.tokenId === tokenId &&
                    isEqualCaseInsensitive(
                      elm.requestData.asset.address,
                      address,
                    ),
                );

                const nftImageURL = found
                  ? found.requestData.asset.assetImageUrl
                  : '';
                const blockExplorerLink = getTokenTrackerLink(
                  address,
                  chainId,
                  null,
                  null,
                  {
                    blockExplorerUrl: rpcPrefs?.blockExplorerUrl ?? null,
                  },
                );

                if (suggestedNfts.length === 1) {
                  return (
                    <Box
                      className="rounded-md confirm-add-suggested-nft__nft-single"
                      key={`confirm-add-suggested-nft__nft-single-${id}`}
                      margin={0}
                      padding={0}
                    >
                      {nftImageURL ? (
                        <img
                          className="confirm-add-suggested-nft__nft-single-image"
                          src={nftImageURL}
                          alt={name || tokenId}
                        />
                      ) : (
                        <NftDefaultImage
                          className="confirm-add-suggested-nft__nft-single-image-default"
                          tokenId={tokenId}
                          name={name || symbol || shortenAddress(address)}
                        />
                      )}
                      <Box
                        className="flex"
                        padding={1}
                        flexDirection={BoxFlexDirection.Row}
                        justifyContent={BoxJustifyContent.Between}
                        alignItems={BoxAlignItems.Center}
                      >
                        <Box
                          className="flex w-full confirm-add-suggested-nft__nft-single-sub-details"
                          flexDirection={BoxFlexDirection.Column}
                          justifyContent={BoxJustifyContent.Evenly}
                          flexWrap={BoxFlexWrap.NoWrap}
                        >
                          {rpcPrefs.blockExplorerUrl ? (
                            <ButtonLink
                              className="confirm-add-suggested-nft__nft-name"
                              href={blockExplorerLink}
                              title={address}
                              target="_blank"
                              size={BUTTON_SIZES.INHERIT}
                            >
                              {name || symbol || shortenAddress(address)}
                            </ButtonLink>
                          ) : (
                            <Text
                              variant={TextVariant.bodyMd}
                              className="confirm-add-suggested-nft__nft-name"
                              title={address}
                            >
                              {name || symbol || shortenAddress(address)}
                            </Text>
                          )}
                          <Text
                            variant={TextVariant.bodyMd}
                            color={TextColor.textAlternative}
                            className="confirm-add-suggested-nft__nft-tokenId"
                          >
                            #{tokenId}
                          </Text>
                        </Box>
                      </Box>
                    </Box>
                  );
                }
                return (
                  <Box
                    className="flex confirm-add-suggested-nft__nft-list-item"
                    flexDirection={BoxFlexDirection.Row}
                    flexWrap={BoxFlexWrap.NoWrap}
                    alignItems={BoxAlignItems.Center}
                    justifyContent={BoxJustifyContent.Between}
                    marginBottom={4}
                    key={`${address}-${tokenId}`}
                  >
                    <Box
                      className="flex"
                      flexDirection={BoxFlexDirection.Row}
                      flexWrap={BoxFlexWrap.NoWrap}
                      alignItems={BoxAlignItems.Center}
                      justifyContent={BoxJustifyContent.Between}
                    >
                      {nftImageURL ? (
                        <img
                          className="confirm-add-suggested-nft__nft-image"
                          src={nftImageURL}
                          alt={name || tokenId}
                        />
                      ) : (
                        <NftDefaultImage className="confirm-add-suggested-nft__nft-image-default" />
                      )}
                      <Box
                        className="flex w-full confirm-add-suggested-nft__nft-sub-details"
                        flexDirection={BoxFlexDirection.Column}
                        justifyContent={BoxJustifyContent.Evenly}
                        flexWrap={BoxFlexWrap.NoWrap}
                      >
                        {rpcPrefs.blockExplorerUrl ? (
                          <ButtonLink
                            className="confirm-add-suggested-nft__nft-name"
                            href={blockExplorerLink}
                            title={address}
                            target="_blank"
                            size={BUTTON_SIZES.INHERIT}
                          >
                            {name || symbol || shortenAddress(address)}
                          </ButtonLink>
                        ) : (
                          <Text
                            variant={TextVariant.bodySm}
                            className="confirm-add-suggested-nft__nft-name"
                            title={address}
                          >
                            {name || symbol || shortenAddress(address)}
                          </Text>
                        )}
                        <Text
                          variant={TextVariant.bodySm}
                          color={TextColor.textAlternative}
                          className="confirm-add-suggested-nft__nft-tokenId"
                        >
                          #{tokenId}
                        </Text>
                      </Box>
                    </Box>
                    <ButtonIcon
                      className="confirm-add-suggested-nft__nft-remove"
                      data-testid={`confirm-add-suggested-nft__nft-remove-${id}`}
                      iconName={IconName.Close}
                      size={ButtonIconSize.Sm}
                      color={IconColor.iconMuted}
                      onClick={(e) => {
                        e.preventDefault();
                        e.stopPropagation();
                        dispatch(
                          rejectPendingApproval(
                            id,
                            serializeError(
                              providerErrors.userRejectedRequest(),
                            ),
                          ),
                        );
                      }}
                    />
                  </Box>
                );
              },
            )}
          </Box>
        </Box>
      </Box>
      <PageContainerFooter
        cancelText={t('cancel')}
        submitText={suggestedNfts.length === 1 ? t('addNft') : t('addNfts')}
        onCancel={handleCancelNftClick}
        onSubmit={handleAddNftsClick}
      />
    </Box>
  );
};

export default ConfirmAddSuggestedNFT;
